-- Generated by `python -m evals.run --snapshot`: signals the real model extracted
-- from the provided data, so the app shows them without an API key. An upsert, so a
-- newer snapshot replaces an older one in a new migration.
ON CONFLICT (client_id) DO UPDATE SET signals = EXCLUDED.signals, dropped = EXCLUDED.dropped, source_hash = EXCLUDED.source_hash, model = EXCLUDED.model, prompt_version = EXCLUDED.prompt_version, input_tokens = EXCLUDED.input_tokens, output_tokens = EXCLUDED.output_tokens, extracted_at = now();
